package pkg

import "fmt"

// Registry holds named entries.
type Registry struct {
	items map[string]string
}

// New returns an empty registry.
func New() *Registry { return &Registry{items: map[string]string{}} }

// Put stores value under name.
func (r *Registry) Put(name, value string) error {
	if name == "" {
		return fmt.Errorf("empty name")
	}
	r.items[name] = value
	return nil
}

// Get returns the value stored under name.
func (r *Registry) Get(name string) (string, bool) {
	v, ok := r.items[name]
	return v, ok
}

// Names lists the stored names.
func (r *Registry) Names() []string {
	var out []string
	for n := range r.items {
		out = append(out, n)
	}
	return out
}

