package pkg

import (
	"reflect"
	"testing"
)

func TestPutTrimsAndRejectsBlank(t *testing.T) {
	r := New()
	if err := r.Put("   ", "x"); err == nil {
		t.Fatal("a blank name was accepted")
	}
	if err := r.Put("  alpha ", "1"); err != nil {
		t.Fatal(err)
	}
	if v, ok := r.Get("alpha"); !ok || v != "1" {
		t.Fatalf("Get(alpha) = %q, %v", v, ok)
	}
}

func TestNamesAreCaseInsensitive(t *testing.T) {
	r := New()
	r.Put("Beta", "2")
	if v, ok := r.Get("BETA"); !ok || v != "2" {
		t.Fatalf("Get(BETA) = %q, %v", v, ok)
	}
	r.Put("beta", "3")
	if got := r.Names(); len(got) != 1 {
		t.Fatalf("Names() = %v, want one name", got)
	}
}

func TestNamesSorted(t *testing.T) {
	r := New()
	for _, n := range []string{"c", "a", "b"} {
		r.Put(n, n)
	}
	if got := r.Names(); !reflect.DeepEqual(got, []string{"a", "b", "c"}) {
		t.Fatalf("Names() = %v", got)
	}
}
